const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer", node: "Code: Parse & Filter" } });
const raw = $input.first().json;
let msg;
try {
  const payload = raw.message || raw.body || raw;
  msg = typeof payload === 'string' ? JSON.parse(payload) : payload;
} catch(e) {
  throw new Error('alice-dms-thumbnailer: Malformed MQTT message: ' + e.message);
}

// Only process successfully inserted documents
if (!msg.inserted) {
  logger.info(`[alice-dms-thumbnailer] Skipping non-inserted document: ${msg.file_path}`);
  return [];
}

if (!msg.weaviate_uuid) {
  logger.warn(`[alice-dms-thumbnailer] Missing weaviate_uuid — skipping: ${JSON.stringify(msg)}`);
  return [];
}

// PROJ-93 (Email) + PROJ-95 (BankTransaction): these types have no NAS
// file_path (their content lives only in Weaviate) - they get a dedicated
// rendering path instead of the file-based one, so they are exempt from the
// file_path requirement below.
const textBased = msg.document_type === 'Email' || msg.document_type === 'BankTransaction';
if (!textBased && !msg.file_path) {
  logger.warn(`[alice-dms-thumbnailer] Missing file_path — skipping: ${JSON.stringify(msg)}`);
  return [];
}

logger.info(`[alice-dms-thumbnailer] Processing: ${msg.weaviate_uuid} ${msg.file_path || '(' + msg.document_type + ', no file_path)'}`);
return [{ json: { ...msg } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer", node: "Code: Merge Mail Text" } });
const resp = $input.first().json;
const original = $('Code: Parse & Filter').first().json;

// PROJ-93: the Email object may have been deleted between the MQTT publish and
// this lookup (e.g. a concurrent backfill/migration run) - a non-2xx status or
// a missing body must not crash the workflow, it must fail like any other
// generate error further down (IF: Generate OK).
const statusCode = resp.statusCode;
const body = resp.body || {};
const props = body.properties || {};

if (!statusCode || statusCode >= 300) {
  logger.warn(`[alice-dms-thumbnailer] Email object lookup failed for ${original.weaviate_uuid}: status=${statusCode}`);
}

// Bounded preview text, same spirit as the existing file-based text preview
// (subject line + a capped slice of the body so a very long email cannot
// blow up the rendered image).
const subject = String(props.subject || '').slice(0, 200);
const content = String(props.content || '').slice(0, 2000);
const mailText = [subject, content].filter(Boolean).join('\n\n');

return [{ json: { ...original, _mail_text: mailText, _mail_lookup_ok: statusCode >= 200 && statusCode < 300 } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer", node: "Code: Extract Thumbnail Path" } });
const resp = $input.first().json;
const body = resp.body || resp;
const thumbPath = body.thumbnail_path || null;
const uuid = body.weaviate_uuid || $('Code: Parse & Filter').first().json.weaviate_uuid;
const docType = $('Code: Parse & Filter').first().json.document_type || 'Document';

if (!thumbPath || !uuid) {
  throw new Error('Missing thumbnail_path or weaviate_uuid in generate response: ' + JSON.stringify(body));
}

logger.info(`[alice-dms-thumbnailer] Thumbnail generated: ${thumbPath}`);
return [{ json: { thumbnail_path: thumbPath, weaviate_uuid: uuid, document_type: docType } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer", node: "Code: Log Result" } });
const resp = $input.first().json;
const statusCode = resp.statusCode || 0;
if (statusCode >= 200 && statusCode < 300) {
  const uuid = $('Code: Extract Thumbnail Path').first().json.weaviate_uuid;
  logger.info(`[alice-dms-thumbnailer] Weaviate PATCH OK for UUID: ${uuid}`);
  return [{ json: { success: true, weaviate_uuid: uuid } }];
} else {
  const uuid = $('Code: Extract Thumbnail Path').first().json.weaviate_uuid;
  logger.warn(`[alice-dms-thumbnailer] Weaviate PATCH failed (HTTP ${statusCode}) for UUID: ${uuid}`);
  return [{ json: { success: false, weaviate_uuid: uuid, status_code: statusCode } }];
}

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer", node: "Code: Log Error" } });
const item = $input.first().json;
const original = $('Code: Parse & Filter').first().json;
const textBased = original.document_type === 'Email' || original.document_type === 'BankTransaction';
const locator = textBased ? ('(' + original.document_type + ', no file_path)') : original.file_path;
logger.warn(`[alice-dms-thumbnailer] Generation failed for: ${original.weaviate_uuid} ${locator} Status: ${item.statusCode}`);
return [{ json: { error: 'thumbnail_generation_failed', weaviate_uuid: original.weaviate_uuid, file_path: original.file_path || null, status_code: item.statusCode } }];
